        if out[0][c]!=bg:
            bars.append((0,c,1))
        if out[h-1][c]!=bg:
            bars.append((h-1,c,-1))
    for r in range(h):
        if out[r][0]!=bg:
            bars.append((r,0,1))
        if out[r][w-1]!=bg:
            bars.append((r,w-1,-1))
    for r,c,dr in bars:
        rr=r+dr
        while 0<=rr<h:
            v=out[rr][c]
            if v==bg:
                out[rr][c]=6 if grid[0][0]==6 else 3
            elif v not in (grid[r][c],):
                out[rr][c]=4
                break
            rr+=dr
    return out
