def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The most common color is the field background. Sparse interior markers
    # determine the ray color; border strips launch rays perpendicular inward.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    border_colors = set(v for v in grid[0] + grid[-1] +
                        [row[0] for row in grid] + [row[-1] for row in grid]
                        if v != background)
    motif_colors = [v for v in counts if v != background and v not in border_colors]
    if not motif_colors:
        return out
    ray_color = max(motif_colors, key=lambda v: counts[v])

    # Rays run from every non-background border cell to the opposite border.
    # Paint background with the motif color and highlight motif cells as 4.
    for c in range(w):
        if grid[0][c] != background:
            for r in range(1, h):
                if grid[r][c] == background:
                    out[r][c] = ray_color
                elif grid[r][c] == ray_color:
                    out[r][c] = 4
        if grid[h-1][c] != background:
            for r in range(h-2, -1, -1):
                if grid[r][c] == background:
                    out[r][c] = ray_color
                elif grid[r][c] == ray_color:
                    out[r][c] = 4
    for r in range(h):
        if grid[r][0] != background:
            for c in range(1, w):
                if grid[r][c] == background:
                    out[r][c] = ray_color
                elif grid[r][c] == ray_color:
                    out[r][c] = 4
        if grid[r][w-1] != background:
            for c in range(w-2, -1, -1):
                if grid[r][c] == background:
                    out[r][c] = ray_color
                elif grid[r][c] == ray_color:
                    out[r][c] = 4
    return out
